import math

def check_n(n):
    """Checks if for all k coprime to n, k^2 == 1 (mod n)."""
    if n < 2:
        return False

    # We only need to check k in the range [1, n-1]
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check the condition k^2 - 1 is a multiple of n
            if (k**2 - 1) % n != 0:
                # Found a counterexample k for this n
                return False
    # All coprime k satisfied the condition
    return True

solutions = []
# Testing up to n=20 to start
for n in range(2, 21):
    if check_n(n):
        solutions.append(n)

print(f"Solutions found up to n=20: {solutions}")

